-- Repair installations that may have applied the first draft of V14 before its
-- template-version insert was corrected. This is idempotent on fresh databases.
CREATE TEMPORARY TABLE di_sample_template_repair (
  category_key VARCHAR(80) NOT NULL,
  template_key VARCHAR(100) NOT NULL,
  display_name VARCHAR(160) NOT NULL,
  description VARCHAR(1000),
  definition JSONB NOT NULL
) ON COMMIT DROP;

