INSERT INTO invitation_template_version(template_id,version_number,definition)
SELECT t.id,1,s.definition
FROM di_sample_template_repair s
JOIN invitation_template t ON t.template_key=s.template_key
WHERE NOT EXISTS (
  SELECT 1 FROM invitation_template_version v
  WHERE v.template_id=t.id AND v.version_number=1
)
ON CONFLICT(template_id,version_number) DO NOTHING;
